// Load editable Markdown records in the browser. The HTML generated by
// Eleventy remains as a no-JavaScript and network-error fallback.
(() => {
  const contentVersion = Date.now();
  let latestModified = 0;

  const node = (tag, className, text) => {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined) element.textContent = text;
    return element;
  };

  const slug = value => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const initials = name => {
    const parts = name.trim().split(/\s+/);
    return `${parts[0]?.[0] || ''}${parts.length > 1 ? parts.at(-1)[0] : ''}`.toUpperCase();
  };
  const dateLabel = value => new Date(`${value}T00:00:00Z`).toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC',
  });
  const surnameSort = (a, b) => {
    const surnameA = a.name.trim().split(/\s+/).at(-1);
    const surnameB = b.name.trim().split(/\s+/).at(-1);
    return surnameA.localeCompare(surnameB, 'en', { sensitivity: 'base' })
      || a.name.localeCompare(b.name, 'en');
  };

  const safeHref = value => {
    if (!value) return '';
    try {
      const url = new URL(value, document.baseURI);
      return ['http:', 'https:'].includes(url.protocol) ? value : '';
    } catch {
      return '';
    }
  };

  const localPath = value => value?.startsWith('/') && !value.startsWith('//') ? `.${value}` : value;

  async function readContent(path) {
    const url = new URL(path, document.baseURI);
    url.searchParams.set('content-version', String(contentVersion));
    const response = await fetch(url, { cache: 'no-store' });
    if (!response.ok) throw new Error(`${path}: ${response.status} ${response.statusText}`);
    const modified = Date.parse(response.headers.get('last-modified') || '');
    if (Number.isFinite(modified)) latestModified = Math.max(latestModified, modified);
    return response.text();
  }

  function parseValue(value) {
    const trimmed = value.trim();
    if (trimmed.startsWith('"') && trimmed.endsWith('"')) {
      try { return JSON.parse(trimmed); } catch { return trimmed.slice(1, -1); }
    }
    if (trimmed.startsWith("'") && trimmed.endsWith("'")) return trimmed.slice(1, -1);
    return trimmed;
  }

  function parseBlock(block) {
    const record = {};
    for (const rawLine of block.split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;
      const separator = line.indexOf(':');
      if (separator < 1) continue;
      const field = line.slice(0, separator).trim();
      record[field] = parseValue(line.slice(separator + 1));
    }
    if (!Object.keys(record).length || record.draft === 'true') return null;
    return record;
  }

  const parseRecords = text => text
    .split(/^\s*---\s*$/m)
    .map(parseBlock)
    .filter(Boolean);

  function parseTalks(text) {
    return text.split(/^\s*---\s*$/m).flatMap(block => {
      const marker = /^abstract:[ \t]*\r?$/m.exec(block);
      const metadata = marker ? block.slice(0, marker.index) : block;
      const record = parseBlock(metadata);
      if (!record) return [];
      record.abstract = marker ? block.slice(marker.index + marker[0].length).trim() : '';
      return [record];
    });
  }

  const emptyMessage = text => node('p', 'empty-events', text);

  function activityRow(item) {
    const article = node('article');
    const time = node('time', '', dateLabel(item.date));
    time.dateTime = item.date;
    article.append(time);

    const content = node('div');
    content.append(node('span', 'kind', item.type));
    const heading = node('h3');
    const href = safeHref(item.link);
    if (href) {
      const link = node('a', '', item.title);
      link.href = href;
      heading.append(link);
    } else {
      heading.textContent = item.title;
    }
    content.append(heading);
    if (item.authors || item.speaker) content.append(node('p', '', item.authors || item.speaker));
    article.append(content);
    return article;
  }

  function renderActivityList(container, entries, emptyText) {
    container.replaceChildren(...(entries.length ? entries.map(activityRow) : [emptyMessage(emptyText)]));
  }

  async function hydrateHomepage() {
    const homepage = document.querySelector('.homepage-activities');
    if (!homepage) return;
    const [upcomingText, pastText, scheduleText] = await Promise.all([
      readContent('./content/upcoming-events.md'),
      readContent('./content/past-events.md'),
      readContent('./content/reading-group/schedule.md'),
    ]);
    const upcoming = parseRecords(upcomingText);
    const past = parseRecords(pastText);
    const schedule = parseRecords(scheduleText)[0];

    const upcomingList = document.querySelector('#upcoming-events .activity-list');
    const pastList = document.querySelector('#past-events-list');
    if (upcomingList) renderActivityList(upcomingList, upcoming, 'No upcoming events are currently scheduled.');
    if (pastList) renderActivityList(pastList, past, 'No past news or events to show.');

    const meeting = document.querySelector('.reading-group');
    if (meeting && schedule) {
      const link = node('a', '', schedule.title);
      link.href = './reading-group.html';
      meeting.replaceChildren(link, document.createTextNode(`. ${schedule.location}, ${schedule.schedule}`));
    }
  }

  function publicationEntry(item) {
    const entry = node('li', 'publication-entry');
    const heading = node('h3');
    const href = safeHref(item.link);
    if (href) {
      const link = node('a', '', item.title);
      link.href = href;
      heading.append(link);
    } else {
      heading.textContent = item.title;
    }
    entry.append(heading, node('p', 'publication-authors', item.authors));
    const meta = node('p', 'publication-meta', item.venue);
    if (item.status) meta.append(node('span', 'publication-status', item.status));
    entry.append(meta);
    return entry;
  }

  async function hydratePublications() {
    const container = document.querySelector('.publication-years');
    if (!container) return;
    const records = parseRecords(await readContent('./content/publications.md'));
    const sorted = records.map((record, index) => ({ ...record, index }))
      .sort((a, b) => Number(b.year) - Number(a.year) || a.index - b.index);
    const groups = new Map();
    for (const item of sorted) {
      if (!groups.has(item.year)) groups.set(item.year, []);
      groups.get(item.year).push(item);
    }
    if (!groups.size) {
      container.replaceChildren(emptyMessage('Publication information will be added soon.'));
      return;
    }
    const sections = [...groups].map(([year, entries]) => {
      const section = node('section', 'publication-year');
      section.setAttribute('aria-labelledby', `year-${year}`);
      const heading = node('h2', '', year);
      heading.id = `year-${year}`;
      const list = node('ul', 'publication-list');
      list.append(...entries.map(publicationEntry));
      section.append(heading, list);
      return section;
    });
    container.replaceChildren(...sections);
  }

  function portrait(person) {
    const frame = node('div', 'person-portrait');
    if (person.image) {
      const image = node('img', 'person-photo');
      image.dataset.person = slug(person.name);
      image.src = localPath(person.image);
      image.alt = `Portrait of ${person.name}`;
      image.width = 220;
      image.height = 275;
      image.loading = 'lazy';
      frame.append(image);
    } else {
      const fallback = node('span', 'person-initials', initials(person.name));
      fallback.setAttribute('aria-hidden', 'true');
      frame.append(fallback);
    }
    return frame;
  }

  function personCard(person, className) {
    const href = safeHref(person.website);
    const card = node(href ? 'a' : 'div', className);
    if (href) card.href = href;
    card.append(portrait(person), node('h3', '', person.name));
    return card;
  }

  function advisorLine(person, facultyIds) {
    const paragraph = node('p', 'person-advisor');
    paragraph.append(document.createTextNode('Advisor: '));
    const advisorId = facultyIds.get(person.advisor);
    if (advisorId) {
      const link = node('a', '', person.advisor);
      link.href = `./people.html#${advisorId}`;
      paragraph.append(link);
    } else {
      paragraph.append(document.createTextNode(person.advisor || '—'));
    }
    return paragraph;
  }

  async function hydratePeople() {
    const facultyList = document.querySelector('.faculty-list');
    const studentList = document.querySelector('.student-list');
    const alumniList = document.querySelector('.alumni-list');
    if (!facultyList || !studentList || !alumniList) return;
    const [facultyText, studentsText, alumniText] = await Promise.all([
      readContent('./content/people/faculty.md'),
      readContent('./content/people/students.md'),
      readContent('./content/people/alumni.md'),
    ]);
    const faculty = parseRecords(facultyText).sort(surnameSort);
    const students = parseRecords(studentsText).sort(surnameSort);
    const alumni = parseRecords(alumniText).map((person, index) => ({ ...person, index }))
      .sort((a, b) => (Number(b.year) || -1) - (Number(a.year) || -1) || a.index - b.index);
    const facultyIds = new Map(faculty.map(person => [person.name, slug(person.name)]));

    const facultyEntries = faculty.map(person => {
      const article = node('article', 'faculty-entry');
      article.id = slug(person.name);
      article.append(personCard(person, 'faculty-card'));
      if (person.research) article.append(node('p', 'faculty-research', person.research));
      return article;
    });
    facultyList.replaceChildren(...(facultyEntries.length ? facultyEntries : [emptyMessage('Faculty information will be added soon.')]))

    const studentEntries = students.map(person => {
      const article = node('article', 'student-entry');
      article.append(personCard(person, 'student-card'));
      const info = node('div', 'person-info');
      info.append(advisorLine(person, facultyIds));
      if (person.research) info.append(node('p', 'person-research', person.research));
      article.append(info);
      return article;
    });
    studentList.replaceChildren(...(studentEntries.length ? studentEntries : [emptyMessage('Current student information will be added soon.')]))

    const alumniEntries = alumni.map(person => {
      const article = node('article', 'alumni-entry');
      const main = node('div', 'alumni-main');
      const href = safeHref(person.website);
      const name = node(href ? 'a' : 'span', 'alumni-name', person.name);
      if (href) name.href = href;
      main.append(name, node('span', 'alumni-year', person.year || '—'));
      const advisor = advisorLine(person, facultyIds);
      advisor.className = 'alumni-advisor';
      main.append(advisor);
      article.append(main);
      if (person.current) article.append(node('p', 'alumni-current', `→ ${person.current}`));
      return article;
    });
    alumniList.replaceChildren(...(alumniEntries.length ? alumniEntries : [emptyMessage('Alumni information will be added soon.')]))
  }

  function semesterForDate(date) {
    const month = Number(date.slice(5, 7));
    return `${month <= 5 ? 'Spring' : month <= 8 ? 'Summer' : 'Fall'} ${date.slice(0, 4)}`;
  }

  function talkRow(item) {
    const article = node('article', 'talk-row');
    const time = node('time', '', dateLabel(item.date));
    time.dateTime = item.date;
    const content = node('div', 'talk-content');
    const heading = node('h3');
    const href = safeHref(item.link);
    if (href) {
      const link = node('a', '', item.title);
      link.href = href;
      heading.append(link);
    } else {
      heading.textContent = item.title;
    }
    content.append(heading);
    const speaker = node('p', 'talk-speaker', item.speaker);
    const slidesHref = safeHref(item.slides);
    if (slidesHref) {
      speaker.append(document.createTextNode(' · '));
      const slides = node('a', '', 'Slides');
      slides.href = slidesHref;
      speaker.append(slides);
    }
    content.append(speaker);
    if (item.abstract) {
      const details = node('details', 'talk-abstract');
      const summary = node('summary', '', 'Abstract');
      const hidden = node('span', 'visually-hidden', ` for ${item.title}`);
      summary.append(hidden);
      const abstract = node('div', 'abstract-content');
      for (const paragraphText of item.abstract.split(/\r?\n\s*\r?\n/)) {
        const cleaned = paragraphText.trim()
          .replace(/\\cite\{([^}]+)\}/g, '[$1]')
          .replace(/\\footnote\{([^}]+)\}/g, ' ($1)');
        if (cleaned) abstract.append(node('p', 'runtime-abstract', cleaned));
      }
      details.append(summary, abstract);
      content.append(details);
    }
    article.append(time, content);
    return article;
  }

  function renderTalkList(container, entries, emptyText) {
    container.replaceChildren(...(entries.length ? entries.map(talkRow) : [emptyMessage(emptyText)]));
  }

  function groupTalks(past, themes) {
    const groups = new Map();
    for (const entry of [...past].sort((a, b) => b.date.localeCompare(a.date))) {
      const label = semesterForDate(entry.date);
      if (!groups.has(label)) groups.set(label, {
        label,
        id: label.toLowerCase().replace(' ', '-'),
        theme: themes.get(label),
        entries: [],
      });
      groups.get(label).entries.push(entry);
    }
    return [...groups.values()];
  }

  async function readReadingGroup() {
    const [scheduleText, upcomingText, pastText, semestersText] = await Promise.all([
      readContent('./content/reading-group/schedule.md'),
      readContent('./content/reading-group/upcoming.md'),
      readContent('./content/reading-group/past.md'),
      readContent('./content/reading-group/semesters.md'),
    ]);
    const schedule = parseRecords(scheduleText)[0] || {};
    const themes = new Map(parseRecords(semestersText).map(item => [item.semester, item.theme]));
    const past = parseTalks(pastText);
    const upcoming = parseTalks(upcomingText);
    const today = new Date().toISOString().slice(0, 10);
    const currentSemester = schedule.semester || semesterForDate(today);
    const semesters = groupTalks(past, themes);
    return { schedule, past, upcoming, semesters, currentSemester };
  }

  async function hydrateReadingGroup() {
    const page = document.querySelector('.reading-group-page');
    if (!page || page.querySelector('#reading-group-archive-list')) return;
    const data = await readReadingGroup();
    const { schedule, upcoming, semesters, currentSemester } = data;
    const heading = page.querySelector('.group-heading h1');
    const description = page.querySelector('.group-description');
    const scheduleLine = page.querySelector('.group-schedule');
    const theme = page.querySelector('.group-theme');
    if (heading && schedule.title) heading.textContent = schedule.title;
    if (description && schedule.description) description.textContent = schedule.description;
    if (scheduleLine) scheduleLine.replaceChildren(
      node('span', '', schedule.schedule || ''), node('span', '', schedule.location || ''),
    );
    if (theme) {
      theme.textContent = schedule.theme || '';
      theme.hidden = !schedule.theme;
    }
    const semesterLabel = page.querySelector('.group-semester');
    if (semesterLabel) semesterLabel.textContent = currentSemester;
    const upcomingList = page.querySelector('#upcoming-talks + .talk-list');
    const currentList = page.querySelector('#semester-talks + .talk-list');
    const current = semesters.find(group => group.label === currentSemester)?.entries || [];
    if (upcomingList) renderTalkList(
      upcomingList,
      upcoming.filter(entry => semesterForDate(entry.date) === currentSemester),
      'The next talk will be announced here.',
    );
    if (currentList) renderTalkList(currentList, current, `Completed talks from ${currentSemester} will appear here.`);
    const sidebar = page.querySelector('.reading-group-sidebar nav');
    if (sidebar) {
      const all = node('a', '', 'All past talks');
      all.href = './reading-group-archive.html';
      const links = semesters.filter(group => group.label !== currentSemester).map(group => {
        const link = node('a', '', group.label);
        link.href = `./reading-group-archive.html#${group.id}`;
        return link;
      });
      sidebar.replaceChildren(all, ...links);
    }
  }

  async function hydrateReadingGroupArchive() {
    const container = document.querySelector('#reading-group-archive-list');
    if (!container) return;
    const { semesters } = await readReadingGroup();
    const navigation = document.querySelector('.semester-navigation');
    if (navigation) {
      navigation.replaceChildren(...semesters.map(group => {
        const link = node('a', '', group.label);
        link.href = `#${group.id}`;
        return link;
      }));
    }
    const sections = semesters.map(group => {
      const section = node('section', 'activity-section');
      section.setAttribute('aria-labelledby', group.id);
      const heading = node('h2', 'ruled-heading', group.label);
      heading.id = group.id;
      section.append(heading);
      if (group.theme) section.append(node('p', 'semester-theme', group.theme));
      const list = node('div', 'talk-list');
      renderTalkList(list, group.entries, '');
      section.append(list);
      return section;
    });
    container.replaceChildren(...(sections.length ? sections : [emptyMessage('Past talks will appear here.')]))
  }

  function updateFooterDate() {
    if (!latestModified) return;
    const updated = document.querySelector('#site-updated');
    if (!updated) return;
    const date = new Date(latestModified);
    updated.dateTime = date.toISOString().slice(0, 10);
    updated.textContent = date.toLocaleDateString('en-US', {
      month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC',
    });
  }

  async function hydrate() {
    const tasks = [
      hydrateHomepage(),
      hydratePublications(),
      hydratePeople(),
      hydrateReadingGroup(),
      hydrateReadingGroupArchive(),
    ];
    const results = await Promise.allSettled(tasks);
    for (const result of results) {
      if (result.status === 'rejected') console.error('Could not load editable site content.', result.reason);
    }
    updateFooterDate();
    document.dispatchEvent(new CustomEvent('content:updated'));
  }

  void hydrate();
})();
